const PARTITION_MAP = {
  "monolithic bay": 1,
  "triptych gallery": 3,
  "cabinet chambers": 6,
  "specimen grid": 12,
  "herbarium matrix": 24,
  "apothecary drawers": 48
};

const TAXONOMY_MAP = {
  "columnar equisetum": { spread: 0.2, lengthMod: 0.85, center: true },
  "feathered polypody": { spread: 0.6, lengthMod: 0.75, center: true },
  "bramble briar":      { spread: 1.2, lengthMod: 0.70, center: false },
  "twining bryony":     { spread: 0.4, lengthMod: 0.85, center: false },
  "tendril passiflora": { spread: 0.8, lengthMod: 0.80, center: false },
  "serpentine rhizome": { spread: 1.5, lengthMod: 0.65, center: false }
};

const TEMPO_MAP = {
  "dormant bud":         { depth: 2, speed: 0.01 },
  "slow vernal creep":   { depth: 3, speed: 0.02 },
  "rhythmic pulse":      { depth: 4, speed: 0.05 },
  "rampant surge":       { depth: 5, speed: 0.08 },
  "hypertrophic tangle": { depth: 6, speed: 0.12 },
  "feral overrun":       { depth: 7, speed: 0.15 }
};

const RECOIL_MAP = {
  "gentle rim deflection":    { factor: 0.2, type: "deflect" },
  "creeping perimeter slide": { factor: 0.4, type: "slide" },
  "glass shudder snap":       { factor: 0.6, type: "snap" },
  "inward spiral tuck":       { factor: 1.2, type: "spiral" },
  "claustrophobic whorl":     { factor: 1.8, type: "spiral" },
  "spastic vortex rebound":   { factor: 2.5, type: "snap" }
};

const PATINA_MAP = {
  "fresh viridian wash":   { bg: "#eef5f0", line: "#2d5a3f", frame: "#8da995" },
  "wilted celadon":        { bg: "#f0f2eb", line: "#647b64", frame: "#b4c2b4" },
  "sunken verdigris":      { bg: "#1a2421", line: "#54997a", frame: "#304d41" },
  "desiccated ochre":      { bg: "#f5ece4", line: "#8b6a4f", frame: "#c4ae9c" },
  "burnt bistre pressing": { bg: "#d6c9b8", line: "#4a3320", frame: "#8f7c68" },
  "iron gall oxidation":   { bg: "#c4bbb2", line: "#282321", frame: "#695e59" }
};

let compartments = [];
let lastDensity = -1;
let ctx;

function buildTreemap(p, targetCount) {
  p.randomSeed(12345);
  compartments = [{x: 20, y: 20, w: 760, h: 760}];
  while(compartments.length < targetCount) {
    let maxArea = 0, largestIdx = 0;
    for (let i = 0; i < compartments.length; i++) {
      let area = compartments[i].w * compartments[i].h;
      if (area > maxArea) { maxArea = area; largestIdx = i; }
    }
    let c = compartments.splice(largestIdx, 1)[0];
    let ratio = p.random(0.35, 0.65);
    if (c.w > c.h) {
      compartments.push({x: c.x, y: c.y, w: c.w * ratio, h: c.h});
      compartments.push({x: c.x + c.w * ratio, y: c.y, w: c.w * (1-ratio), h: c.h});
    } else {
      compartments.push({x: c.x, y: c.y, w: c.w, h: c.h * ratio});
      compartments.push({x: c.x, y: c.y + c.h * ratio, w: c.w, h: c.h * (1-ratio)});
    }
  }
}

function branch(p, x, y, angle, len, depth, c, tax, recoil, t) {
  if (depth <= 0 || len < 2) return;

  let nx = x + p.cos(angle) * len;
  let ny = y + p.sin(angle) * len;

  let dX = Math.min(nx - c.x, c.x + c.w - nx);
  let dY = Math.min(ny - c.y, c.y + c.h - ny);
  let hit = (dX < 10 || dY < 10);

  if (hit) {
    let rType = recoil.type;
    let shudder = (rType === "snap") ? p.sin(t * 15 + depth) * 0.5 : 0;
    let spiral = (rType === "spiral") ? 0.8 : 0.2;
    let direction = (nx > c.x + c.w/2) ? -1 : 1;
    angle += (recoil.factor * spiral + shudder) * direction;
    nx = p.constrain(nx, c.x + 8, c.x + c.w - 8);
    ny = p.constrain(ny, c.y + 8, c.y + c.h - 8);
  }

  ctx.moveTo(x, y);
  ctx.lineTo(nx, ny);

  let sway = p.sin(t + x * 0.02) * 0.1;
  let nLen = len * tax.lengthMod;

  branch(p, nx, ny, angle - tax.spread + sway, nLen, depth - 1, c, tax, recoil, t);
  branch(p, nx, ny, angle + tax.spread - sway, nLen, depth - 1, c, tax, recoil, t);
  if (tax.center) {
    branch(p, nx, ny, angle + sway * 1.5, nLen * 1.15, depth - 1, c, tax, recoil, t);
  }
}

p.setup = function() {
  p.createCanvas(800, 800);
  ctx = p.drawingContext;
  p.strokeJoin(p.ROUND);
  p.strokeCap(p.ROUND);
};

p.draw = function() {
  const density = p.getSynthVar("partition_density") || "monolithic bay";
  const tax = TAXONOMY_MAP[p.getSynthVar("botanical_taxonomy") || "columnar equisetum"];
  const tempo = TEMPO_MAP[p.getSynthVar("growth_tempo") || "dormant bud"];
  const recoil = RECOIL_MAP[p.getSynthVar("boundary_recoil") || "gentle rim deflection"];
  const patina = PATINA_MAP[p.getSynthVar("specimen_patina") || "fresh viridian wash"];

  const count = PARTITION_MAP[density];
  if (count !== lastDensity) {
    buildTreemap(p, count);
    lastDensity = count;
  }

  p.background(patina.bg);
  let t = p.frameCount * tempo.speed;

  ctx.beginPath();
  ctx.strokeStyle = patina.frame;
  ctx.lineWidth = 3;
  for (let c of compartments) {
    ctx.rect(c.x, c.y, c.w, c.h);
    let m = 12;
    let bLen = Math.max(15, Math.min(c.w, c.h) * 0.12);

    ctx.moveTo(c.x + m, c.y + m + bLen);
    ctx.lineTo(c.x + m, c.y + m);
    ctx.lineTo(c.x + m + bLen, c.y + m);

    ctx.moveTo(c.x + c.w - m, c.y + m + bLen);
    ctx.lineTo(c.x + c.w - m, c.y + m);
    ctx.lineTo(c.x + c.w - m - bLen, c.y + m);

    ctx.moveTo(c.x + m, c.y + c.h - m - bLen);
    ctx.lineTo(c.x + m, c.y + c.h - m);
    ctx.lineTo(c.x + m + bLen, c.y + c.h - m);

    ctx.moveTo(c.x + c.w - m, c.y + c.h - m - bLen);
    ctx.lineTo(c.x + c.w - m, c.y + c.h - m);
    ctx.lineTo(c.x + c.w - m - bLen, c.y + c.h - m);
  }
  ctx.stroke();

  ctx.beginPath();
  ctx.strokeStyle = patina.line;
  ctx.lineWidth = 1.5;

  for (let c of compartments) {
    let areaRatio = (c.w * c.h) / (760 * 760);
    let depthLimit = Math.floor(p.map(areaRatio, 0, 1, 3, 7));
    let actualDepth = Math.min(tempo.depth, depthLimit);

    let baseX = c.x + c.w / 2;
    let baseY = c.y + c.h - 10;

    let budPulse = p.sin(t * 2) * 4;
    let bRadius = Math.max(8, c.w * 0.015) + budPulse;
    ctx.moveTo(baseX + bRadius, baseY);
    ctx.arc(baseX, baseY, bRadius, 0, p.TWO_PI);

    let initLen = c.h * 0.3;
    branch(p, baseX, baseY, -p.HALF_PI, initLen, actualDepth, c, tax, recoil, t);
  }
  ctx.stroke();
};
